/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name="sender">xFormRun</param>
/// <param name="e">FormEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormEventHandler(formStr(SalesCopying), FormEventType::Initialized)]
public static void SalesCopying_OnInitialized(xFormRun sender, FormEventArgs e)
{
    FormRun                 formRun = sender;
    FormTabPageControl      tabPageSales, tabPageQuote;

    tabPageSales = formRun.design().controlName(formControlStr(SalesCopying, TabPageSales));
    tabPageQuote = formRun.design().controlName(formControlStr(SalesCopying, TabPageQuotation));

    tabPageQuote.expand();
    tabPageSales.collapse();


}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">FormDataSourceEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(SalesCopying, CustQuotationJour), FormDataSourceEventType::QueryExecuting)]
public static void CustQuotationJour_OnQueryExecuting(FormDataSource sender, FormDataSourceEventArgs e)
{
    QueryBuildDataSource    qbds;
    QueryBuildRange         qbr;
    utcdatetime             respDate;
    CustQuotationJour       custQuotationJour;
    SalesQuotationNumOfDays expNumOfDays;

    qbds = sender.queryBuildDataSource();
    custQuotationJour = sender.cursor();
    expNumOfDays = !CustQuotationJour.AVANoExpiryOverrun  ?  AVASalesParameters::find().SalesQuotationNumOfDays : 0;

    qbr = SysQuery::findOrCreateRange(qbds, fieldNum(CustQuotationJour, RespiteDate));
    respDate = DateTimeUtil::addDays(DateTimeUtil::getSystemDateTime(), -expNumOfDays);
    qbr.value(SysQuery::range(DateTimeUtil::date(respDate), DateTimeUtil::maxValue()));
}
